// The panel's texts, English and German (the language follows Home Assistant).

const { MAX_ROWS } = await import(`./shared.js${new URL(import.meta.url).search}`);

// a duration in its largest whole unit, rounded down: 3599 s is "59 min", not "60 min"
function span(s, days) {
  if (s < 60) return `${s} s`;
  if (s < 3600) return `${Math.floor(s / 60)} min`;
  if (s < 86400) return `${Math.floor(s / 3600)} h`;
  return days(Math.floor(s / 86400));
}

